var hidePostImg = false;

function initPostImages(context)
{
    if (hidePostImg) return;
    var $in_spoilers = $('div.sp-body var.postImg', context);
    $('var.postImg', context).not($in_spoilers).each(function(){
        var $v = $(this);
        var src = $v.attr('title');
        var $img = $('<img src="'+ src +'" class="'+ $v.attr('class') +'" alt="pic" />');
        $img = fixPostImage($img);
        var maxW = ($v.hasClass('postImgAligned')) ? postImgAligned_MaxWidth : postImg_MaxWidth;
        $img.bind('click', function(){ return imgFit(this, maxW); });
        if (user.opt_js.i_aft_l) {
            $('#preload').append($img);
            var loading_icon = '<a href="'+ src +'" target="_blank"><img src="{SITE_URL}styles/images/pic_loading.gif" alt="" /></a>';
            $v.html(loading_icon);
            if ($.browser.msie) {
                $v.after('<wbr>');
            }
            $img.one('load', function(){
                imgFit(this, maxW);
                $v.empty().append(this);
            });
        }
        else {
            $img.one('load', function(){ imgFit(this, maxW) });
            $v.empty().append($img);
            if ($.browser.msie) {
                $v.after('<wbr>');
            }
        }
    });
    $('var.posterImg', context).each(function(){
        var $v = $(this);
        var src = $v.attr('title');
        var $img = $('<img src="'+ src +'" class="'+ $v.attr('class') +'" width="260px;" alt="Загружается..." border="0" />');
        $img = fixPostImage($img);
        $v.empty().append($img);
        if ($.browser.msie) {
            $v.after('<wbr>');
        }
    });
}

